 async function internalGeometry(pageId,width,target=page){const found=await target.evaluate(pageId=>{const section=document.getElementById(pageId),issues=[],visible=e=>e.getClientRects().length&&getComputedStyle(e).visibility!=='hidden';const name=e=>e.id||String(e.className||'').slice(0,100)||e.tagName;for(const e of section.querySelectorAll('div,section,article,label,form,table,tbody,tr,td,strong,output')){if(!visible(e)||e.clientWidth<10)continue;const cs=getComputedStyle(e);if(['hidden','clip'].includes(cs.overflowX)&&e.scrollWidth>e.clientWidth+3&&cs.textOverflow!=='ellipsis'){const bounds=e.getBoundingClientRect(),walker=document.createTreeWalker(e,NodeFilter.SHOW_TEXT);let t,bad=false;while(t=walker.nextNode()){if(!t.textContent.trim()||!visible(t.parentElement))continue;let scrolled=false;for(let a=t.parentElement;a&&a!==e;a=a.parentElement){if(['auto','scroll'].includes(getComputedStyle(a).overflowX)&&a.scrollWidth>a.clientWidth+2){scrolled=true;break;}}if(scrolled)continue;const range=document.createRange();range.selectNodeContents(t);for(const r of range.getClientRects())if(r.left<bounds.left-2||r.right>bounds.right+2)bad=true;}if(bad)issues.push({type:'clipped',node:name(e),client:e.clientWidth,scroll:e.scrollWidth});}}for(const parent of section.querySelectorAll('.form-grid,.flow-stat-grid,.flow-summary,.investment-overview-grid,.debt-page-overview,#growthProjectionSummary,.flow-tabs,.pft-style-choice-grid,.theme-options,.settings-data-actions,.family-tile-grid,.retirement-account-summary')){if(!visible(parent))continue;const p=parent.getBoundingClientRect();if(['auto','scroll'].includes(getComputedStyle(parent).overflowX))continue;const children=[...parent.children].filter(e=>visible(e)&&getComputedStyle(e).position!=='absolute').map(e=>({name:name(e),r:e.getBoundingClientRect()}));for(const {name:n,r} of children)if(r.left<p.left-2||r.right>p.right+2)issues.push({type:'child outside grid',node:name(parent),child:n,left:r.left,right:r.right,parentLeft:p.left,parentRight:p.right});for(let i=0;i<children.length;i++)for(let j=i+1;j<children.length;j++){const a=children[i],b=children[j];if(Math.min(a.r.right,b.r.right)-Math.max(a.r.left,b.r.left)>2&&Math.min(a.r.bottom,b.r.bottom)-Math.max(a.r.top,b.r.top)>2)issues.push({type:'overlap',parent:name(parent),a:a.name,b:b.name});}}return issues;},pageId);auditIssues.push(...found.map(i=>({page:pageId,width,...i})));}
 async function projectionGeometry(target=page){const issues=await target.evaluate(()=>{const box=e=>{const r=e.getBoundingClientRect();return{x:r.x,y:r.y,right:r.right,bottom:r.bottom,width:r.width,height:r.height}};const out=[];const controls=document.getElementById('growthProjectionControls'),c=box(controls);for(const e of controls.querySelectorAll('.form-grid > .form-group,.growth-horizon-control,.growth-contribution-toggle')){if(!e.getClientRects().length)continue;const r=box(e);if(r.x<c.x-1||r.right>c.right+1||r.bottom>c.bottom+1)out.push({type:'control outside panel',class:e.className,r,c});}const groups=[...controls.querySelectorAll('.form-grid > .form-group')].map(box);if(groups.length===2){const a=groups[0],b=groups[1];if(Math.min(a.right,b.right)-Math.max(a.x,b.x)>1&&Math.min(a.bottom,b.bottom)-Math.max(a.y,b.y)>1)out.push({type:'overlapping groups',groups});}const summary=document.getElementById('growthProjectionSummary'),p=box(summary),cards=[...summary.children].map(box);cards.forEach((r,i)=>{if(r.x<p.x-1||r.right>p.right+1)out.push({type:'forecast card clipped',i,r,p});});for(let i=0;i<cards.length;i++)for(let j=i+1;j<cards.length;j++){const a=cards[i],b=cards[j];if(Math.min(a.right,b.right)-Math.max(a.x,b.x)>1&&Math.min(a.bottom,b.bottom)-Math.max(a.y,b.y)>1)out.push({type:'forecast cards overlap',i,j});}return out;});assert.deepEqual(issues,[]);}
